<?php
declare(strict_types=1);
require_once __DIR__.'/includes/auth.php';requireAdmin();require_once __DIR__.'/config/conexion.php';$errors=[];$message=$_SESSION['flash']??'';unset($_SESSION['flash']);
$users=$pdo->query('SELECT d.idUser,d.nombre,d.apellidos,l.usuario FROM users_data d INNER JOIN users_login l ON l.idUser=d.idUser ORDER BY d.apellidos,d.nombre')->fetchAll();$selected=(int)($_GET['usuario']??$_POST['selectedUser']??0);$validUser=false;foreach($users as $u)if($u['idUser']===$selected)$validUser=true;
if($_SERVER['REQUEST_METHOD']==='POST') {if(!csrfValid('admin_citas',$_POST['csrf_token']??null))$errors[]='La solicitud no es válida.';elseif(!$validUser)$errors[]='Selecciona un usuario válido.';else{$action=$_POST['action']??'';$id=(int)($_POST['idCita']??0);$fecha=trim((string)($_POST['fecha_cita']??''));$motivo=trim((string)($_POST['motivo_cita']??''));if($action==='create'||$action==='update'){if(!validDate($fecha))$errors[]='La fecha debe ser válida y no anterior a hoy.';if($motivo==='')$errors[]='El motivo es obligatorio.';}if(($action==='update'||$action==='delete')&&!$errors){$q=$pdo->prepare('SELECT 1 FROM citas WHERE idCita=? AND idUser=?');$q->execute([$id,$selected]);if(!$q->fetchColumn())$errors[]='La cita no pertenece al usuario seleccionado.';}if(!$errors&&$action==='create'){$pdo->prepare('INSERT INTO citas (idUser,fecha_cita,motivo_cita) VALUES (?,?,?)')->execute([$selected,$fecha,$motivo]);flash('Cita creada.');}elseif(!$errors&&$action==='update'){$pdo->prepare('UPDATE citas SET fecha_cita=?,motivo_cita=? WHERE idCita=? AND idUser=?')->execute([$fecha,$motivo,$id,$selected]);flash('Cita actualizada.');}elseif(!$errors&&$action==='delete'){$pdo->prepare('DELETE FROM citas WHERE idCita=? AND idUser=?')->execute([$id,$selected]);flash('Cita eliminada.');}if(!$errors){header('Location: citaciones-administracion.php?usuario='.$selected);exit;}}}
$citas=[];if($validUser){$q=$pdo->prepare('SELECT * FROM citas WHERE idUser=? ORDER BY fecha_cita');$q->execute([$selected]);$citas=$q->fetchAll();}$editId=(int)($_GET['editar']??0);$editing=null;foreach($citas as $c)if($c['idCita']===$editId)$editing=$c;$tituloPagina='Administración de citaciones | Salud Cercana';require __DIR__.'/includes/header.php';
?>
<main class="content-section"><div class="section-heading"><p class="eyebrow">Administración</p><h1>Citaciones</h1></div><?php if($message):?><p class="alert alert-success"><?=e($message)?></p><?php endif;?><?php foreach($errors as $error):?><p class="alert alert-error"><?=e($error)?></p><?php endforeach;?><section class="form-card"><form method="get"><label>Selecciona un usuario<select name="usuario" onchange="this.form.submit()"><option value="">-- Seleccionar --</option><?php foreach($users as $u):?><option value="<?=$u['idUser']?>" <?=$u['idUser']===$selected?'selected':''?>><?=e($u['apellidos'].', '.$u['nombre'].' ('.$u['usuario'].')')?></option><?php endforeach;?></select></label><button class="button">Ver citas</button></form></section><?php if($validUser):?><section class="form-card spaced-card"><h2><?=$editing?'Editar cita':'Crear cita para usuario seleccionado'?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken('admin_citas'))?>"><input type="hidden" name="selectedUser" value="<?=$selected?>"><input type="hidden" name="action" value="<?=$editing?'update':'create'?>"><?php if($editing):?><input type="hidden" name="idCita" value="<?=$editing['idCita']?>"><?php endif;?><div class="form-grid"><label>Fecha<input type="date" name="fecha_cita" required value="<?=e($editing['fecha_cita']??'')?>"></label><label class="full-width">Motivo<textarea name="motivo_cita" required><?=e($editing['motivo_cita']??'')?></textarea></label></div><button class="button">Guardar</button><?php if($editing):?> <a href="citaciones-administracion.php?usuario=<?=$selected?>">Cancelar</a><?php endif;?></form></section><section class="spaced-card"><h2>Citas</h2><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Motivo</th><th>Acciones</th></tr></thead><tbody><?php foreach($citas as $c):?><tr><td><?=e($c['fecha_cita'])?></td><td><?=e($c['motivo_cita'])?></td><td><a href="citaciones-administracion.php?usuario=<?=$selected?>&editar=<?=$c['idCita']?>">Editar</a><form class="inline-form" method="post" onsubmit="return confirm('¿Eliminar esta cita?');"><input type="hidden" name="csrf_token" value="<?=e(csrfToken('admin_citas'))?>"><input type="hidden" name="selectedUser" value="<?=$selected?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="idCita" value="<?=$c['idCita']?>"><button class="link-button">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?></main><?php require __DIR__.'/includes/footer.php'; ?>
